mapper.select:
SELECT INSTANCE_ID FROM WF_TERMINAL_EVENT_OUTBOX
WHERE DELETED=0 AND ((STATUS='PENDING' AND NEXT_ATTEMPT_AT <= #{nextAttemptAt})
   OR (STATUS='IN_PROGRESS' AND CLAIMED_UNTIL <= #{claimedUntil})) ORDER BY NEXT_ATTEMPT_AT ASC LIMIT #{limit}

mapper.update:
UPDATE WF_TERMINAL_EVENT_OUTBOX SET STATUS='IN_PROGRESS', CLAIMED_BY=#{owner}, CLAIMED_UNTIL=#{until}, UPDATED_AT=#{now}
WHERE DELETED=0 AND (INSTANCE_ID IN #{id}
AND ((STATUS='PENDING' AND NEXT_ATTEMPT_AT <= #{now}) OR (STATUS='IN_PROGRESS' AND CLAIMED_UNTIL <= #{now})))
